result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "app/main.py", "content": """"ETag/cursor-based sync pull feed.

Every mutation to /items appends an immutable row to a changes log with a
monotonically increasing ``seq``. Clients pull deltas with
``GET /sync?cursor=<last seen seq>`` and receive every change newer than the
cursor plus the new cursor (the highest seq in the response). A client with
no cursor bootstraps from a full snapshot instead.
"""

from __future__ import annotations

import itertools
import threading
from typing import Any, Optional

from fastapi import FastAPI, HTTPException, Query
from pydantic import BaseModel, Field

app = FastAPI(title="sync-pull-feed")

_lock = threading.Lock()
_seq = itertools.count(1)

# canonical state: item_id -> payload dict
items: dict[int, dict[str, Any]] = {}
# changes log: {seq, op, id, data}
changes: list[dict[str, Any]] = []


class ItemIn(BaseModel):
    name: str = Field(min_length=1)
    value: int = Field(ge=0)


def _append_change(op: str, item_id: int, data: Optional[dict]) -> int:
    """Record one change row. Caller must hold _lock."""
    seq = next(_seq)
    changes.append({"seq": seq, "op": op, "id": item_id, "data": data})
    return seq


@app.post("/items", status_code=201)
def create_item(item: ItemIn) -> dict:
    with _lock:
        item_id = max(items, default=0) + 1
        payload = item.model_dump()
        items[item_id] = payload
        seq = _append_change("create", item_id, payload)
    return {"id": item_id, "seq": seq}


@app.get("/items/{item_id}")
def get_item(item_id: int) -> dict:
    with _lock:
        if item_id not in items:
            raise HTTPException(status_code=404, detail="not found")
        return {"id": item_id, **items[item_id]}


@app.put("/items/{item_id}")
def update_item(item_id: int, item: ItemIn) -> dict:
    with _lock:
        if item_id not in items:
            raise HTTPException(status_code=404, detail="not found")
        payload = item.model_dump()
        items[item_id] = payload
        seq = _append_change("update", item_id, payload)
    return {"id": item_id, "seq": seq}


@app.delete("/items/{item_id}", status_code=204)
def delete_item(item_id: int) -> None:
    with _lock:
        if item_id not in items:
            raise HTTPException(status_code=404, detail="not found")
        del items[item_id]
        _append_change("delete", item_id, None)


@app.get("/sync")
def sync(cursor: Optional[int] = Query(default=None, ge=0)) -> dict:
    """Pull feed.

    - No cursor: full snapshot + current head seq.
    - With cursor: all changes with seq > cursor, oldest first,
      plus next_cursor = seq of newest returned change (or head).
    """
    with _lock:
        head = max((c["seq"] for c in changes), default=0)
        if cursor is None:
            snapshot = {str(i): dict(data) for i, data in items.items()}
            return {"snapshot": snapshot, "next_cursor": head}

        pending = [dict(c) for c in changes if c["seq"] > cursor]
        # next_cursor must never go backwards even when nothing changed
        next_cursor = max([head, cursor])
    return {"changes": pending, "next_cursor": next_cursor}
